func testNotaFiscalToManyAddOpNTFCartaCorecaoNves(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a NotaFiscal
	var b, c, d, e CartaCorecaoNfe

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, notaFiscalDBTypes, false, strmangle.SetComplement(notaFiscalPrimaryKeyColumns, notaFiscalColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*CartaCorecaoNfe{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, cartaCorecaoNfeDBTypes, false, strmangle.SetComplement(cartaCorecaoNfePrimaryKeyColumns, cartaCorecaoNfeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*CartaCorecaoNfe{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddNTFCartaCorecaoNves(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.NTFID != first.NTFID {
			t.Error("foreign key was wrong value", a.NTFID, first.NTFID)
		}
		if a.NTFID != second.NTFID {
			t.Error("foreign key was wrong value", a.NTFID, second.NTFID)
		}

		if first.R.NTF != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.NTF != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.NTFCartaCorecaoNves[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.NTFCartaCorecaoNves[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.NTFCartaCorecaoNves().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
